source='''def transform(grid):
    height, width = len(grid), len(grid[0])
    cells = {(r, c) for r in range(height) for c in range(width) if grid[r][c] == 8}
    placements = []

    for r in range(height - 1):
        for c in range(width - 1):
            box = {(r, c), (r, c + 1), (r + 1, c), (r + 1, c + 1)}
            if box <= cells:
                placements.append((box, 1))
            color_by_missing_corner = {
                (r, c): 2,
                (r, c + 1): 4,
                (r + 1, c): 3,
                (r + 1, c + 1): 5,
            }
            for missing in box:
                triomino = box - {missing}
                if triomino <= cells:
                    placements.append((triomino, color_by_missing_corner[missing]))

    by_cell = {cell: [] for cell in cells}
    for shape, color in placements:
        for cell in shape:
            by_cell[cell].append((shape, color))

    def cover(remaining):
        if not remaining:
            return []
        cell = min(remaining, key=lambda p: sum(shape <= remaining for shape, _ in by_cell[p]))
        for shape, color in by_cell[cell]:
            if shape <= remaining:
                rest = cover(remaining - shape)
                if rest is not None:
                    return [(shape, color)] + rest
        return None

    solution = cover(cells)
    if solution is None:
        raise ValueError("Input cannot be tiled by the demonstrated square and L shapes")
    output = [[0] * width for _ in range(height)]
    for shape, color in solution:
        for r, c in shape:
            output[r][c] = color
    return output
